import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, uniform, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, SphereGeometry, Color, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const group = new Group();
  group.name = 'hub-journal-card-3';

  // inner pivot so hover/press transforms never fight the adapter-set scenePosition
  const pivot = new Group();
  group.add(pivot);

  const W = 1.5;
  const H = W / (512 / 320); // preserve atlas aspect (1.6)

  // --- Substrate: a thin extruded machined-metal frame for the 3D card feel ---
  const frameGeo = new BoxGeometry(W + 0.06, H + 0.06, 0.05);
  const frameMat = new MeshStandardNodeMaterial({
    color: surface,
    metalness: 0.5,
    roughness: 0.55,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = -0.025;
  pivot.add(frame);

  // subtle accent inlay ring underneath (machined bevel hint) — bright accent strip on bottom edge
  const edgeGeo = new BoxGeometry(W + 0.06, 0.018, 0.052);
  const edgeMat = new MeshStandardNodeMaterial({
    color: accent,
    metalness: 0.35,
    roughness: 0.45,
    emissive: accent,
    emissiveIntensity: 0.0,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, -(H + 0.06) / 2 - 0.009, -0.025);
  pivot.add(edge);

  // --- Image plane (content) ---
  const imgGeo = new PlaneGeometry(W, H);
  const imgMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
    color: surface,
    toneMapped: false,
  });
  const img = new Mesh(imgGeo, imgMat);
  img.position.z = 0.0;
  pivot.add(img);

  // load image texture asynchronously onto the plane
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      imgMat.map = tex;
      imgMat.color = new Color(0xffffff);
      imgMat.needsUpdate = true;
      texStorage.set('img', tex);
    }).catch(() => {});
  }

  // --- Focus accent bar (top edge) — appears on hover/focus ---
  const focusGeo = new PlaneGeometry(W + 0.06, 0.02);
  const focusMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
    side: DoubleSide,
    toneMapped: false,
  });
  const focusBar = new Mesh(focusGeo, focusMat);
  focusBar.position.set(0, (H + 0.06) / 2 + 0.011, 0.031);
  pivot.add(focusBar);

  // --- Stock badge (data-binding target: trpc.inventory.status.inStock -> stockBadge) ---
  // represented as an accent emissive dot; runtime sets truth via userData.handlers.setStock(bool)
  const badgeBaseMat = new MeshStandardNodeMaterial({
    color: ink,
    metalness: 0.4,
    roughness: 0.6,
  });
  const badgeBaseGeo = new PlaneGeometry(0.34, 0.12);
  const badgeBase = new Mesh(badgeBaseGeo, badgeBaseMat);
  badgeBase.position.set(-(W / 2) + 0.2, -(H / 2) + 0.12, 0.032);
  pivot.add(badgeBase);

  const dotMat = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 0.15,
    metalness: 0.2,
    roughness: 0.4,
  });
  const dotGeo = new SphereGeometry(0.03, 16, 16);
  const dot = new Mesh(dotGeo, dotMat);
  dot.position.set(-(W / 2) + 0.1, -(H / 2) + 0.12, 0.04);
  pivot.add(dot);

  // expose as binding target
  group.userData.stockBadge = dot;

  // ------------- gsap housekeeping -------------
  const texStorage = new Map();
  const timelines = [];
  const addTl = (t) => { timelines.push(t); return t; };

  let stockState = true; // optimistic default until binding resolves

  // ------------- interaction state -------------
  let hovering = false;
  let pressed = false;

  function hoverStart() {
    if (hovering) return;
    hovering = true;
    addTl(gsap.to(pivot.position, { y: 0.15, duration: 0.6, ease: 'power3.out', overwrite: 'auto' }));
    addTl(gsap.to(pivot.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.55, ease: 'power2.out', overwrite: 'auto' }));
    addTl(gsap.to(pivot.rotation, { x: -0.05, y: 0.03, duration: 0.55, ease: 'power2.out', overwrite: 'auto' }));
    addTl(gsap.to(focusMat, { opacity: 1, duration: 0.32, ease: 'power2.out' }));
    addTl(gsap.to(edgeMat, { emissiveIntensity: 0.9, duration: 0.4, ease: 'power2.out' }));
  }

  function hoverEnd() {
    if (!hovering) return;
    hovering = false;
    addTl(gsap.to(pivot.position, { y: 0, duration: 0.55, ease: 'power3.out', overwrite: 'auto' }));
    addTl(gsap.to(pivot.scale, { x: 1, y: 1, z: 1, duration: 0.6, ease: 'power4.out', overwrite: 'auto' }));
    addTl(gsap.to(pivot.rotation, { x: 0, y: 0, duration: 0.55, ease: 'power2.out', overwrite: 'auto' }));
    addTl(gsap.to(focusMat, { opacity: 0, duration: 0.3, ease: 'power2.in' }));
    addTl(gsap.to(edgeMat, { emissiveIntensity: 0, duration: 0.4, ease: 'power2.in' }));
  }

  function onClick() {
    // press-down then weighted-settle
    pressed = true;
    addTl(gsap.to(pivot.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.in(2)', overwrite: 'auto',
      onComplete: () => {
        addTl(gsap.to(pivot.scale, { x: hovering ? 1.02 : 1, y: hovering ? 1.02 : 1, z: 1, duration: 0.9, ease: 'power4.out', onComplete: () => { pressed = false; } }));
      }
    }));
    ctx.emit('hub-journal.select', { id: 'hub-journal-card-3', source: 'journal-card' });
  }

  function onFocus() {
    addTl(gsap.to(focusMat, { opacity: 1, duration: 0.25, ease: 'power2.out' }));
    addTl(gsap.to(pivot.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 0.35, ease: 'power2.out', overwrite: 'auto' }));
  }

  function onBlur() {
    addTl(gsap.to(focusMat, { opacity: 0, duration: 0.25, ease: 'power2.in' }));
    if (!hovering) addTl(gsap.to(pivot.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power2.out', overwrite: 'auto' }));
  }

  // runtime-driven stock status setter (binding: trpc.inventory.status.inStock -> stockBadge)
  function setStock(inStock) {
    stockState = !!inStock;
    if (stockState) {
      addTl(gsap.to(dotMat, { emissiveIntensity: 1.2, duration: 0.4, ease: 'power2.out' }));
      addTl(gsap.to(dot.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'back.out(2)' }));
    } else {
      addTl(gsap.to(dotMat, { emissiveIntensity: 0.08, duration: 0.4, ease: 'power2.in' }));
      addTl(gsap.to(dot.scale, { x: 0.6, y: 0.6, z: 0.6, duration: 0.4, ease: 'power2.in' }));
    }
  }

  // attach handlers to userData (runtime touches these — never addEventListener)
  group.userData.handlers = {
    hoverStart,
    hoverEnd,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
    setStock,
  };

  // ------------- cleanup -------------
  group.userData.cleanup = () => {
    timelines.forEach((t) => { try { t.kill(); } catch (_) {} });
    timelines.length = 0;
    texStorage.forEach((tex) => { try { tex.dispose(); } catch (_) {} });
    texStorage.clear();
    [
      frameGeo, edgeGeo, imgGeo, focusGeo, badgeBaseGeo, dotGeo,
    ].forEach((g) => { try { g.dispose(); } catch (_) {} });
    [
      frameMat, edgeMat, imgMat, focusMat, badgeBaseMat, dotMat,
    ].forEach((m) => { try { m.dispose(); } catch (_) {} });
    while (group.children.length) group.remove(group.children[0]);
  };

  return group;
}
